const rows = $input.all().map(function(i){ return i.json; });
const luna = rows.find(function(r){ return r.agent_id === 'reminders'; });
return [{ json: { enabled: luna ? !!luna.enabled : false } }];

const config = $('Demo Config').first().json;
const now = config.as_of_override ? new Date(config.as_of_override) : new Date();
const appts = $('Get Appointments (Reminders)').all().map(function(i){ return i.json; }).filter(function(r){ return r.appointment_id && r.status === 'Confirmed'; });
const patients = $('Get Patients (Reminders)').all().map(function(i){ return i.json; }).filter(function(r){ return r.patient_id; });
const priorEvents = $('Get Prior Reminder Events').all().map(function(i){ return i.json; }).filter(function(r){ return r.event_id && r.type === 'reminder_prepared'; });
function patientById(id){ return patients.find(function(p){ return p.patient_id === id; }); }
function alreadyPrepared(relatedId, tag){ return priorEvents.some(function(e){ return e.related_id === relatedId && e.description && e.description.indexOf(tag) !== -1; }); }
const stages = [ { key: '48h', minH: 36, maxH: 60 }, { key: '24h', minH: 12, maxH: 36 } ];
const eligibleReminders = []; const skippedReminders = [];
appts.forEach(function(a){
  const start = new Date(a.start_time);
  const hoursUntil = (start - now) / 3600000;
  const patient = patientById(a.patient_id);
  stages.forEach(function(s){
    if (hoursUntil >= s.minH && hoursUntil < s.maxH) {
      const tag = a.appointment_id + ':' + s.key;
      if (!patient) { skippedReminders.push({ appointment_id: a.appointment_id, stage: s.key, reason: 'Patient not found' }); return; }
      if (!patient.consent_appointment) { skippedReminders.push({ appointment_id: a.appointment_id, stage: s.key, reason: 'No appointment consent' }); return; }
      if (alreadyPrepared(a.appointment_id, s.key)) { skippedReminders.push({ appointment_id: a.appointment_id, stage: s.key, reason: 'Already prepared' }); return; }
      eligibleReminders.push({ appointment_id: a.appointment_id, patient_id: a.patient_id, stage: s.key, start_time: a.start_time, treatment: a.treatment, tag: tag, message: 'Reminder: your ' + a.treatment + ' appointment is on ' + start.toISOString() + '. Reply to confirm or reschedule.' });
    }
  });
});
const eligibleRecall = []; const skippedRecall = [];
patients.forEach(function(p){
  if (!p.recall_due_date) return;
  const due = new Date(p.recall_due_date);
  if (due <= now) {
    const hasUpcoming = appts.some(function(a){ return a.patient_id === p.patient_id && new Date(a.start_time) > now; });
    if (hasUpcoming) { skippedRecall.push({ patient_id: p.patient_id, reason: 'Already has upcoming appointment' }); return; }
    if (!p.consent_marketing) { skippedRecall.push({ patient_id: p.patient_id, reason: 'Opted out of marketing/recall' }); return; }
    if (alreadyPrepared(p.patient_id, 'recall')) { skippedRecall.push({ patient_id: p.patient_id, reason: 'Already prepared' }); return; }
    eligibleRecall.push({ patient_id: p.patient_id, tag: p.patient_id + ':recall', message: 'Hi ' + p.name + ", it's time for your routine check-up - would you like to book?" });
  }
});
return [{ json: { practice_id: config.practice_id, as_of: now.toISOString(), eligible_reminders: eligibleReminders, skipped_reminders: skippedReminders, eligible_recall: eligibleRecall, skipped_recall: skippedRecall } }];

const c = $('Compute Candidates').first().json;
const rows = [];
c.eligible_reminders.forEach(function(r){ rows.push({ json: { demo_session_id: 'demo1', approval_id: 'apr_' + r.tag + '_' + Date.now(), practice_id: c.practice_id, kind: 'reminder', status: 'Pending', payload: r.message, recipients: r.patient_id, requested_by: 'Luna', created_at: new Date().toISOString() } }); });
c.eligible_recall.forEach(function(r){ rows.push({ json: { demo_session_id: 'demo1', approval_id: 'apr_' + r.tag + '_' + Date.now(), practice_id: c.practice_id, kind: 'recall', status: 'Pending', payload: r.message, recipients: r.patient_id, requested_by: 'Luna', created_at: new Date().toISOString() } }); });
return rows;

const c = $('Compute Candidates').first().json;
const rows = [];
c.eligible_reminders.forEach(function(r){ rows.push({ json: { demo_session_id: 'demo1', event_id: 'evt_' + Date.now() + '_' + Math.random().toString(36).slice(2,6), practice_id: c.practice_id, type: 'reminder_prepared', description: 'Prepared ' + r.stage + ' reminder for ' + r.appointment_id, related_id: r.appointment_id, created_at: new Date().toISOString() } }); });
c.eligible_recall.forEach(function(r){ rows.push({ json: { demo_session_id: 'demo1', event_id: 'evt_' + Date.now() + '_' + Math.random().toString(36).slice(2,6), practice_id: c.practice_id, type: 'reminder_prepared', description: 'Prepared recall for ' + r.patient_id, related_id: r.patient_id, created_at: new Date().toISOString() } }); });
return rows;
